 9	    public static int[] countSort(int[] values) {
10	        Objects.requireNonNull(values, "values");
11	
12	        if (values.length == 0) {
13	            return new int[0];
14	        }
15	
16	        int maxValue = findMaxValue(values);
17	        int[] counts = buildCounts(values, maxValue);
18	        accumulateCounts(counts);
19	        return buildSortedArray(values, counts);
20	    }
