22	    private static int findMaxValue(int[] values) {
23	        int maxValue = validateNonNegative(values[0]);
24	
25	        for (int i = 1; i < values.length; i++) {
26	            int value = validateNonNegative(values[i]);
27	            if (value > maxValue) {
28	                maxValue = value;
29	            }
30	        }
31	
32	        return maxValue;
33	    }
