45	    private static void accumulateCounts(int[] counts) {
46	        for (int i = 1; i < counts.length; i++) {
47	            counts[i] += counts[i - 1];
48	        }
49	    }
50	
51	    private static int[] buildSortedArray(int[] values, int[] counts) {
52	        int[] sortedValues = new int[values.length];
53	
54	        for (int i = values.length - 1; i >= 0; i--) {
55	            int value = values[i];
